"""S11 scope revision of the master (applied once to v0.3; re-running fails by design; kept as the record of every textual change).
Each change replaces one whole paragraph (identified by a unique opening) or one exact substring."""
import sys, pathlib
p = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".") / "proposal" / "IRAA_PROPOSAL_EN_MASTER.md"
L = p.read_text().split("\n")
def para(prefix, new):
    idx = [i for i, l in enumerate(L) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix[:60], len(idx)); L[idx[0]] = new
def sub(old, new):
    s = "\n".join(L); assert s.count(old) == 1, old[:70]; L[:] = s.replace(old, new).split("\n")
def drop(prefix):
    idx = [i for i, l in enumerate(L) if l.startswith(prefix)]
    assert len(idx) == 1, prefix[:60]; del L[idx[0]]

